<style>
*{box-sizing:border-box}html{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f8fafc;color:#0f172a}body{margin:0;min-height:100vh;background:#f8fafc;color:#0f172a;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer}img,svg{display:block;max-width:100%}[x-cloak]{display:none!important}
:root{--slate-50:#f8fafc;--slate-100:#f1f5f9;--slate-200:#e2e8f0;--slate-300:#cbd5e1;--slate-400:#94a3b8;--slate-500:#64748b;--slate-600:#475569;--slate-700:#334155;--slate-800:#1e293b;--slate-900:#0f172a;--slate-950:#020617;--indigo-50:#eef2ff;--indigo-100:#e0e7ff;--indigo-500:#6366f1;--indigo-600:#4f46e5;--indigo-700:#4338ca;--emerald-50:#ecfdf5;--emerald-200:#a7f3d0;--emerald-700:#047857;--amber-50:#fffbeb;--amber-200:#fde68a;--amber-800:#92400e;--rose-50:#fff1f2;--rose-200:#fecdd3;--rose-600:#e11d48;--rose-700:#be123c;--white:#fff}
.iod-shell{min-height:100vh;display:grid;grid-template-columns:280px minmax(0,1fr)}.iod-sidebar{min-height:100vh;background:linear-gradient(180deg,#020617 0%,#0f172a 100%);color:#cbd5e1;border-right:1px solid #1e293b;display:flex;flex-direction:column;position:sticky;top:0;height:100vh}.iod-brand{display:flex;align-items:center;gap:12px;padding:24px;border-bottom:1px solid #1e293b}.iod-brand-mark{width:42px;height:42px;border-radius:14px;background:linear-gradient(135deg,#6366f1,#4f46e5);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;box-shadow:0 10px 24px rgba(79,70,229,.25)}.iod-brand-title{display:block;font-weight:750;color:#fff;font-size:16px}.iod-brand-subtitle{display:block;font-size:12px;color:#64748b;margin-top:2px}.iod-nav{padding:18px 14px;display:flex;flex-direction:column;gap:6px;flex:1}.iod-nav-label{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#475569;font-weight:700;padding:8px 12px}.iod-nav-link{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:12px;color:#94a3b8;font-size:14px;font-weight:600;transition:.18s ease}.iod-nav-link:hover,.iod-nav-link.is-active{background:#111827;color:#fff}.iod-nav-dot{width:8px;height:8px;border-radius:999px;background:#475569}.iod-nav-link.is-active .iod-nav-dot{background:#818cf8;box-shadow:0 0 0 4px rgba(99,102,241,.12)}.iod-userbox{padding:16px;border-top:1px solid #1e293b}.iod-usercard{background:rgba(15,23,42,.9);border:1px solid #1e293b;border-radius:16px;padding:14px}.iod-user-name{font-size:14px;font-weight:700;color:#fff}.iod-user-email{font-size:12px;color:#64748b;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.iod-content{min-width:0}.iod-topbar{position:sticky;top:0;z-index:30;height:68px;background:rgba(255,255,255,.94);backdrop-filter:blur(14px);border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;padding:0 28px}.iod-topbar-title{font-size:14px;font-weight:750;color:#0f172a}.iod-topbar-subtitle{font-size:12px;color:#94a3b8;margin-top:2px}.iod-main{padding:30px;max-width:1500px;margin:0 auto}.iod-alert{border-radius:14px;padding:12px 14px;margin-bottom:18px;font-size:14px;border:1px solid}.iod-alert-success{background:#ecfdf5;border-color:#a7f3d0;color:#047857}.iod-alert-warning{background:#fffbeb;border-color:#fde68a;color:#92400e}.iod-alert-error{background:#fff1f2;border-color:#fecdd3;color:#be123c}
.iod-page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:24px}.iod-eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.12em;font-weight:800;color:#6366f1;margin-bottom:8px}.iod-page-title{font-size:30px;line-height:1.15;font-weight:800;letter-spacing:-.025em;margin:0;color:#0f172a}.iod-page-subtitle{font-size:14px;color:#64748b;line-height:1.65;margin:8px 0 0}.iod-grid{display:grid;gap:18px}.iod-grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.iod-grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.iod-grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}.iod-card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;box-shadow:0 1px 2px rgba(15,23,42,.03),0 8px 24px rgba(15,23,42,.04)}.iod-card-pad{padding:22px}.iod-card-title{font-size:16px;font-weight:750;color:#0f172a}.iod-card-subtitle{font-size:13px;color:#64748b;margin-top:4px}.iod-stat{padding:20px}.iod-stat-label{font-size:12px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.06em}.iod-stat-value{font-size:28px;font-weight:800;color:#0f172a;margin-top:8px;letter-spacing:-.03em}.iod-stat-meta{font-size:12px;color:#94a3b8;margin-top:5px}.iod-list{display:flex;flex-direction:column}.iod-list-item{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 18px;border-top:1px solid #f1f5f9}.iod-list-item:first-child{border-top:0}.iod-list-item:hover{background:#f8fafc}.iod-list-title{font-weight:700;color:#0f172a}.iod-list-meta{font-size:12px;color:#64748b;margin-top:4px}.iod-empty{padding:34px;text-align:center;color:#64748b}.iod-empty strong{display:block;color:#334155;font-size:16px;margin-bottom:6px}
.iod-btn-primary,.iod-btn-secondary,.iod-btn-danger,.iod-btn-ghost{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:11px;padding:10px 14px;font-size:14px;font-weight:750;border:1px solid transparent;transition:.18s ease}.iod-btn-primary{background:#4f46e5;color:#fff;box-shadow:0 6px 16px rgba(79,70,229,.18)}.iod-btn-primary:hover{background:#4338ca;transform:translateY(-1px)}.iod-btn-secondary{background:#fff;color:#334155;border-color:#cbd5e1}.iod-btn-secondary:hover{background:#f8fafc;border-color:#94a3b8}.iod-btn-danger{background:#fff1f2;color:#be123c;border-color:#fecdd3}.iod-btn-danger:hover{background:#ffe4e6}.iod-btn-ghost{background:transparent;color:#64748b}.iod-btn-ghost:hover{background:#f1f5f9;color:#0f172a}.iod-label{display:block;font-size:13px;font-weight:700;color:#334155;margin-bottom:7px}.iod-input,.iod-select,.iod-textarea{width:100%;border:1px solid #cbd5e1;background:#fff;color:#0f172a;border-radius:11px;padding:11px 12px;outline:none;transition:.16s ease;box-shadow:0 1px 2px rgba(15,23,42,.03)}.iod-input:focus,.iod-select:focus,.iod-textarea:focus{border-color:#6366f1;box-shadow:0 0 0 4px rgba(99,102,241,.12)}.iod-textarea{min-height:110px;resize:vertical}.iod-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.iod-field{margin-bottom:16px}.iod-help{font-size:12px;color:#94a3b8;margin-top:6px}.iod-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.iod-badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.iod-badge-success{background:#ecfdf5;color:#047857}.iod-badge-warning{background:#fffbeb;color:#92400e}.iod-badge-danger{background:#fff1f2;color:#be123c}.iod-badge-neutral{background:#f1f5f9;color:#475569}.iod-table-wrap{overflow:auto;background:#fff;border:1px solid #e2e8f0;border-radius:18px;box-shadow:0 1px 2px rgba(15,23,42,.03)}.iod-table{width:100%;border-collapse:collapse;min-width:720px}.iod-table th{padding:12px 16px;background:#f8fafc;border-bottom:1px solid #e2e8f0;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:#64748b;font-weight:800}.iod-table td{padding:14px 16px;border-top:1px solid #f1f5f9;font-size:14px;color:#334155;vertical-align:top}.iod-table tbody tr:hover{background:#fafafa}.iod-section{margin-top:24px}.iod-section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px}.iod-section-title{font-size:18px;font-weight:800;color:#0f172a;margin:0}
.iod-login{min-height:100vh;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(420px,.85fr);background:#020617}.iod-login-hero{position:relative;overflow:hidden;padding:64px;display:flex;align-items:flex-end;background:radial-gradient(circle at 15% 15%,rgba(99,102,241,.35),transparent 28%),radial-gradient(circle at 85% 80%,rgba(14,165,233,.28),transparent 30%),linear-gradient(145deg,#020617 0%,#0f172a 100%);color:#fff}.iod-login-hero:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:36px 36px}.iod-login-copy{position:relative;z-index:1;max-width:640px}.iod-login-pill{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);padding:8px 12px;border-radius:999px;font-size:13px;color:#cbd5e1;backdrop-filter:blur(8px)}.iod-login-title{font-size:58px;line-height:1;font-weight:850;letter-spacing:-.05em;margin:26px 0 16px}.iod-login-text{font-size:18px;line-height:1.7;color:#cbd5e1;max-width:560px}.iod-login-features{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:28px}.iod-login-feature{border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);border-radius:14px;padding:14px;color:#dbeafe;font-size:13px}.iod-login-panel{display:flex;align-items:center;justify-content:center;padding:32px;background:#f8fafc}.iod-login-card{width:100%;max-width:430px;background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:30px;box-shadow:0 30px 80px rgba(15,23,42,.12)}.iod-login-logo{width:50px;height:50px;border-radius:15px;background:linear-gradient(135deg,#6366f1,#4f46e5);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:850;box-shadow:0 14px 30px rgba(79,70,229,.24)}.iod-login-heading{font-size:26px;font-weight:850;letter-spacing:-.03em;margin:20px 0 6px}.iod-login-subheading{font-size:14px;color:#64748b;line-height:1.6;margin:0 0 24px}.iod-login-footer{text-align:center;font-size:11px;color:#94a3b8;margin-top:20px}
@media(max-width:1100px){.iod-grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}.iod-login{grid-template-columns:1fr}.iod-login-hero{display:none}}
@media(max-width:820px){.iod-shell{display:block}.iod-sidebar{position:relative;height:auto;min-height:0}.iod-nav{flex-direction:row;flex-wrap:wrap}.iod-userbox{display:none}.iod-content{width:100%}.iod-topbar{position:relative;padding:0 18px}.iod-main{padding:20px}.iod-grid-2,.iod-grid-3,.iod-grid-4,.iod-form-grid{grid-template-columns:1fr!important}.iod-page-head{align-items:flex-start;flex-direction:column}.iod-list-item{align-items:flex-start}.iod-login-panel{padding:20px}.iod-login-card{padding:24px}.iod-login-title{font-size:42px}}
@media(max-width:520px){.iod-main{padding:16px}.iod-page-title{font-size:26px}.iod-card-pad,.iod-stat{padding:17px}.iod-topbar{height:auto;min-height:62px;padding-top:10px;padding-bottom:10px}.iod-topbar>div:last-child{display:none}}
